import os
import time
import datetime
from typing import Optional

from ute_ue import ute_ue
from taf.rfrl.bts.devices.du.logs_collecting.basic_logs import GnbLog
from taf.rfrl.utilities.test_config import get_log_path
from taf.rfrl.ue.ue_attach_verification import UeAttachVerification


class ue_operations:
    def __init__(self):
        self._ue = ute_ue()
        self._gnb_log = GnbLog()
        self._attach_verification = UeAttachVerification()

    def require_ue(self, ue_alias: str, capabilities: str) -> None:
        """
        Takes UE with given alias and capabilities, to be used in further test operations.

        :param ue_alias: Alias of the UE to be used.
        :param capabilities: Capabilities of the UE to be used, e.g. REAL_ANDROID_UE.

        :return: None
        """

        self._ue.require_ue(ue_alias, capabilities)

    def attach_and_verify_ue_properly_attached(self, ue_alias: str, pci_5g: int, pci_4g: Optional[int] = None,
                                               attach_type: str = 'nsa', awaited_messages: Optional[str] = None,
                                               forbidden_messages: Optional[str] = None, timeout: int = 60,
                                               forbidden_messages_check: bool = True, bts_id: int = 0, du_id: int = 0,
                                               interface: str = 'any',
                                               additional_options_for_tcpdump: Optional[str] = None,
                                               pcap_file: Optional[str] = None, log_dir: Optional[str] = None,
                                               raise_on_error: bool = True) -> None:
        """
        Attaches the UE with the given alias to the network. Attach cna be either
        NSA (Non-Standalone) or SA (Standalone).

        :param ue_alias: Alias of the UE to be used.
        :param pci_5g: PCI (Physical Cell Identity) of the 5G cell to attach to.
        :param pci_4g: Optional PCI of the 4G cell to attach to (required for NSA attach).
        :param attach_type: Type of attach, either 'nsa' (Non-Standalone) or 'sa' (Standalone).
        :param awaited_messages: Messages to be awaited during the attach process.
        :param forbidden_messages: Messages that should not be present during the attach process.
        :param timeout: Timeout for the attach operation in seconds.
        :param forbidden_messages_check: Whether to check for forbidden messages in the attach process.
        :param bts_id: ID of the BTS to collect attach logs from.
        :param du_id: ID of the BTS DU to collect attach logs from.
        :param interface: Network interface to use for capturing packets (default is 'any').
        :param additional_options_for_tcpdump: Additional options for tcpdump command.
        :param pcap_file: Name of the pcap file to save the captured packets.
        :param log_dir: Directory to save the pcap file.
        :param raise_on_error: Whether attach verification should raise exceptions on errors.

        :return: None

        :raises ValueError: If attach_type is not 'nsa' or 'sa'.
        """

        if attach_type.lower() not in ['nsa', 'sa']:
            raise ValueError("Attach_type must be either 'nsa' or 'sa'")

        if pcap_file is None:
            timestamp = datetime.datetime.now().strftime("%Y_%m_%dT%H_%M_%S")
            pcap_file = f"{ue_alias}_attach_{timestamp}.pcap"
        if log_dir is None:
            log_dir = get_log_path()

        self._attach(
            ue_alias=ue_alias,
            pci_5g=pci_5g,
            pci_4g=pci_4g,
            attach_type=attach_type,
            timeout=timeout,
            bts_id=bts_id,
            du_id=du_id,
            interface=interface,
            forbidden_messages_check=forbidden_messages_check,
            additional_options_for_tcpdump=additional_options_for_tcpdump,
            pcap_file=pcap_file,
            log_dir=log_dir,
            awaited_messages=awaited_messages,
            forbidden_messages=forbidden_messages,
            raise_on_error=raise_on_error
        )

    def detach_ue(self, ue_alias: str, timeout: int = 60) -> None:
        """
        Detaches the UE with the given alias from the network.

        :param ue_alias: Alias of the UE to be detached.
        :param timeout: Timeout for the detach operation in seconds.

        :return: None
        """

        self._ue.detach_ue(ue_alias, timeout)

    def _attach(self, ue_alias: str, pci_5g: int, pci_4g: int, attach_type: str, timeout: int,
                bts_id: int, du_id: int, interface: str, forbidden_messages_check: bool,
                additional_options_for_tcpdump: str, pcap_file: str, log_dir: str,
                awaited_messages: Optional[str] = None, forbidden_messages: Optional[str] = None,
                raise_on_error: bool = True) -> None:

        pcap_file_path = os.path.join(log_dir, pcap_file)
        self._gnb_log.start_tcpdump_on_smod(interface=interface, capture_file=pcap_file, count=0, duration=0,
                                            background=True, timeout=timeout+20, bts_id=bts_id, du_id=du_id,
                                            additional_options=additional_options_for_tcpdump)
        time.sleep(5)
        self._ue.attach_ue(ue_alias, timeout)
        time.sleep(5)
        self._gnb_log.stop_tcpdump_on_smod(bts_id=bts_id, du_id=du_id)
        self._gnb_log.download_tcpdump_from_bts(interface="FCT", log_file_name=pcap_file, bts_id=bts_id)

        if attach_type.lower() == 'nsa':
            self._attach_verification.verify_nsa_attach(
                ue_alias=ue_alias,
                pci_5g=pci_5g,
                pci_4g=pci_4g,
                awaited_messages=awaited_messages,
                forbidden_messages=forbidden_messages,
                pcap_file=pcap_file_path,
                forbidden_messages_check=forbidden_messages_check,
                raise_on_error=raise_on_error
            )
        elif attach_type.lower() == 'sa':
            self._attach_verification.verify_sa_attach(
                ue_alias=ue_alias,
                pci_5g=pci_5g,
                awaited_messages=awaited_messages,
                forbidden_messages=forbidden_messages,
                pcap_file=pcap_file_path,
                forbidden_messages_check=forbidden_messages_check,
                raise_on_error=raise_on_error
            )
